action.command:
cat > /tmp/v.php <<'EOF'
<?php
$m = \Drupal::service('module_handler');
foreach (['ctools','focal_point','key','oauth2_client','openculturas_discussions','openculturas_faq','openculturas_openstreetmap','openculturas_section','phpass','simplei','views_conditional','views_local_tasks'] as $x) {
  echo str_pad($x,32) . ($m->moduleExists($x)?'ENABLED':'DISABLED') . PHP_EOL;
}
EOF
cd /workspace && cp /tmp/v.php /workspace/v_tmp.php && su ddevuser -c "ddev drush php:script v_tmp.php" 2>&1 | tail -14; rm -f /workspace/v_tmp.php

